def fizzbuzz(n: int) -> list[str]:
    """Devuelve una lista de strings del 1 al n con la regla FizzBuzz."""
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s: str) -> int:
    """
    Recibe un string como '1h30m', '45m' o '2h' y devuelve la cantidad total de MINUTOS como entero.
    """
    horas = 0
    minutos = 0

    for char in s:
        if char == 'h':
            horas = int(s[:s.index(char)])
        elif char == 'm':
            minutos = int(s[:s.index(char)])

    return horas * 60 + minutos

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    inicio = 0
    fin = len(lista) - 1

    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inicio = medio + 1
        else:
            fin = medio - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
