def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos."""
    if not 1 <= n <= 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = []
    for valor, simbolo in valores:
        while n >= valor:
            resultado.append(simbolo)
            n -= valor
    return ''.join(resultado)

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    current_elemento = lista[0]
    current_longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == current_elemento:
            current_longitud += 1
        else:
            if current_longitud > max_longitud:
                max_longitud = current_longitud
                max_elemento = current_elemento
            current_elemento = lista[i]
            current_longitud = 1

    if current_longitud > max_longitud:
        max_longitud = current_longitud
        max_elemento = current_elemento

    return (max_elemento, max_longitud)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase."""
    palabras = s.split('_')
    return palabras[0].lower() + ''.join(palabra.capitalize() for palabra in palabras[1:])

def a_snake(s: str) -> str:
    """Convierte camelCase o PascalCase a snake_case."""
    result = []
    for i, char in enumerate(s):
        if char.isupper():
            if i > 0 and s[i - 1].islower():
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a: int, b: int) -> int:
    """Calcula el máximo común divisor de dos enteros no negativos.

    El MCD de un número con 0 es ese número.
    """
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    if not s:
        return s

    resultado = []
    i = 0
    while i < len(s):
        caracter = s[i]
        contador = 1
        while i + contador < len(s) and s[i + contador] == caracter:
            contador += 1

        codificado = caracter + str(contador)
        if len(codificado) < len(caracter) + 1:
            resultado.append(codificado)
        else:
            resultado.append(caracter)

        i += contador

    return ''.join(resultado) if len(''.join(resultado)) < len(s) else s

def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del texto están
    correctamente balanceados y anidados. Un texto vacío está balanceado.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())

    for char in s:
        if char in openers:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return not stack

