def formatear_bytes(n: int) -> str:
    """Convierte una cantidad de bytes a texto legible usando base 1024.

    Args:
        n: Cantidad de bytes (entero no negativo).

    Returns:
        String con la cantidad formateada (ej: '1.5 KB', '0 B').
    """
    if n == 0:
        return "0 B"

    unidades = ["B", "KB", "MB", "GB"]
    valor = float(n)

    for i in range(len(unidades)):
        if valor < 1024:
            if i == 0:
                return f"{int(valor)} {unidades[i]}"
            else:
                return f"{valor:.1f} {unidades[i]}"
        valor /= 1024

    return f"{valor:.1f} TB"

