def fusionar(intervalos):
    if not intervalos:
        return []

    intervalos.sort()
    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        if inicio <= fusionados[-1][1]:
            fusionados[-1] = (fusionados[-1][0], max(fusionados[-1][1], fin))
        else:
            fusionados.append((inicio, fin))

    return fusionados

def mediana(nums):
    if not nums:
        return None
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    if n % 2 == 0:
        return (nums_sorted[n // 2 - 1] + nums_sorted[n // 2]) / 2
    else:
        return nums_sorted[n // 2]

