def contar_islas(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    filas, cols = len(grid), len(grid[0])
    islas = 0

    def dfs(r: int, c: int) -> None:
        if (
            r < 0 or r >= filas
            or c < 0 or c >= cols
            or grid[r][c] == 0
        ):
            return
        grid[r][c] = 0
        dfs(r - 1, c)
        dfs(r + 1, c)
        dfs(r, c - 1)
        dfs(r, c + 1)

    for i in range(filas):
        for j in range(cols):
            if grid[i][j] == 1:
                islas += 1
                dfs(i, j)

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # borrado
                    dp[i][j - 1],    # inserción
                    dp[i - 1][j - 1] # sustitución
                )
    return dp[m][n]

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not any(c.isupper() for c in p):
        return False
    if not any(c.islower() for c in p):
        return False
    if not any(c.isdigit() for c in p):
        return False
    if not any(not c.isalnum() for c in p):
        return False
    return True

