def sumar_romanos(a: str, b: str) -> str:
    """Suma dos números romanos y devuelve el resultado en romano."""
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    inverso = {v: k for k, v in valores.items()}

    def romano_a_entero(s: str) -> int:
        total = 0
        prev = 0
        for char in reversed(s):
            curr = valores[char]
            if curr < prev:
                total -= curr
            else:
                total += curr
            prev = curr
        return total

    def entero_a_romano(n: int) -> str:
        if n == 0:
            return ""
        result = []
        while n > 0:
            for val, sym in valores.items():
                if n >= val:
                    n -= val
                    result.append(sym)
                    break
        return "".join(result)

    entero_a = romano_a_entero(a)
    entero_b = romano_a_entero(b)
    resultado = entero_a + entero_b
    return entero_a_romano(resultado)

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    valor = d
    for parte in partes:
        if isinstance(valor, dict) and parte in valor:
            valor = valor[parte]
        else:
            return defecto
    return valor

